css:
#tongsci1-3-3-1-cell3d .cl-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: radial-gradient(circle at 50% 42%, #ffffff 0%, #eef3f2 55%, #d9e3e4 100%); }
#tongsci1-3-3-1-cell3d .cl-stage canvas { touch-action: none; cursor: grab; }
#tongsci1-3-3-1-cell3d .cl-stage .now-chip { top: auto; bottom: 14px; max-width: calc(100% - 32px); }
#tongsci1-3-3-1-cell3d .cl-tools { position: absolute; right: 14px; top: 12px; display: flex; gap: 8px; z-index: 3; }
#tongsci1-3-3-1-cell3d .cl-tools .btn { font-size: 19px !important; padding: 8px 14px !important; }
#tongsci1-3-3-1-cell3d .cl-tabs { position: absolute; left: 14px; top: 12px; display: flex; gap: 10px; z-index: 3; }
#tongsci1-3-3-1-cell3d .cl-tab { display: flex; align-items: center; gap: 8px; padding: 6px 14px 6px 8px; border: 2px solid var(--ink); border-radius: 12px; background: rgba(251, 252, 249, .9); font: 700 20px var(--f-body); color: var(--ink-2); cursor: pointer; box-shadow: 0 3px 0 var(--ink); }
#tongsci1-3-3-1-cell3d .cl-tab svg { width: 64px; height: 48px; display: block; }
#tongsci1-3-3-1-cell3d .cl-tab[aria-pressed="true"] { background: color-mix(in srgb, var(--hl) 60%, #fff); color: var(--ink); transform: translateY(2px); box-shadow: 0 1px 0 var(--ink); }
#tongsci1-3-3-1-cell3d .cl-tab:focus-visible { outline: 4px solid var(--hl); outline-offset: 2px; }
#tongsci1-3-3-1-cell3d .cl-tab.pulse { animation: tongsci1-3-3-1-cell3d--cl-pulse 1.4s ease-in-out infinite; }
@keyframes tongsci1-3-3-1-cell3d--cl-pulse { 50% { box-shadow: 0 3px 0 var(--ink), 0 0 0 7px color-mix(in srgb, var(--hl) 80%, transparent); } }
#tongsci1-3-3-1-cell3d .cl-tag { pointer-events: auto; cursor: pointer; font-size: 18px; padding: 2px 10px; transition: opacity .25s, background .25s; }
#tongsci1-3-3-1-cell3d .cl-tag:focus-visible { outline: 4px solid var(--hl); }
#tongsci1-3-3-1-cell3d .cl-tag.on { background: var(--hl); font-size: 21px; z-index: 2; }
#tongsci1-3-3-1-cell3d .cl-tag.dim { opacity: .35; }
#tongsci1-3-3-1-cell3d .cl-tag.pv { background: #fff4c2; border-color: #a07800; }
#tongsci1-3-3-1-cell3d .cl-out { margin: 0; font-size: 20px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 7px 14px; min-height: 2.9em; }
#tongsci1-3-3-1-cell3d .cl-card { border: 2px solid var(--ink); border-radius: 12px; background: var(--paper-2); padding: 10px 16px 12px; display: grid; align-content: start; gap: 8px; flex: 1 1 auto; min-height: 0; overflow: auto; }
#tongsci1-3-3-1-cell3d .cl-card h3 { margin: 0; font: 800 30px/1.2 var(--f-display); color: var(--ink); border-left: 10px solid var(--c); padding-left: 12px; }
#tongsci1-3-3-1-cell3d .cl-card p { margin: 0; font-size: 20px; line-height: 1.5; }
#tongsci1-3-3-1-cell3d .cl-card .cl-empty { color: var(--ink-3); }
#tongsci1-3-3-1-cell3d .cl-card dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; font-size: 19px; line-height: 1.4; }
#tongsci1-3-3-1-cell3d .cl-card dt { font-weight: 800; color: var(--ink-2); }
#tongsci1-3-3-1-cell3d .cl-card dd { margin: 0; }
#tongsci1-3-3-1-cell3d .cl-yes, #tongsci1-3-3-1-cell3d .cl-no, #tongsci1-3-3-1-cell3d .cl-na { font-weight: 800; padding: 0 8px; border-radius: 6px; margin-right: 4px; }
#tongsci1-3-3-1-cell3d .cl-yes { background: var(--good-soft); color: var(--good); }
#tongsci1-3-3-1-cell3d .cl-no { background: #fde2dd; color: #b23a22; }
#tongsci1-3-3-1-cell3d .cl-na { background: var(--grid); color: var(--ink-2); }
#tongsci1-3-3-1-cell3d .cl-cell { display: inline-block; font-weight: 700; padding: 0 10px; border-radius: 999px; border: 2px solid var(--rule); color: var(--ink-3); margin-right: 6px; text-decoration: line-through; }
#tongsci1-3-3-1-cell3d .cl-cell.on { border-color: var(--ink); color: var(--ink); text-decoration: none; background: var(--accent-soft); }
#tongsci1-3-3-1-cell3d .cl-card .cl-tip { font-size: 18px; color: var(--ink-2); border-top: 1.5px dashed var(--rule); padding-top: 5px; }
#tongsci1-3-3-1-cell3d .cl-path { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: 24px; flex: none; }
#tongsci1-3-3-1-cell3d .cl-path li { position: relative; font: 700 18px var(--f-body); padding: 4px 10px; border: 2px dashed var(--rule); border-radius: 999px; color: var(--ink-3); white-space: nowrap; }
#tongsci1-3-3-1-cell3d .cl-path li + li::before { content: "→"; position: absolute; left: -21px; top: 4px; color: var(--ink-3); }
#tongsci1-3-3-1-cell3d .cl-path li.ok { border-style: solid; border-color: var(--good); background: var(--good-soft); color: var(--good); }
#tongsci1-3-3-1-cell3d .cl-path.bad { animation: u-shake .45s ease; }

